-- name: InsertAppScan :one
-- Team scope: one app.scan run's row, recorded as it starts ('running') or with a final result.
INSERT INTO app_scans (team_id, app_id, server_id, release_id, image, status, trivy_version,
    critical_count, high_count, medium_count, low_count, unknown_count, findings, truncated, error,
    triggered_by, created_by, started_at, finished_at)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('server_id'), sqlc.narg('release_id'), sqlc.arg('image'),
    sqlc.arg('status'), sqlc.arg('trivy_version'), sqlc.arg('critical_count'), sqlc.arg('high_count'),
    sqlc.arg('medium_count'), sqlc.arg('low_count'), sqlc.arg('unknown_count'), sqlc.arg('findings'),
    sqlc.arg('truncated'), sqlc.arg('error'), sqlc.arg('triggered_by'), sqlc.narg('created_by'),
    sqlc.narg('started_at'), sqlc.narg('finished_at'))
RETURNING *;

-- name: ListAppScans :many
-- Any member: an app's scans, newest first.
SELECT * FROM app_scans WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id')
  ORDER BY created_at DESC LIMIT sqlc.arg('lim') OFFSET sqlc.arg('off');

-- name: LastAppScan :one
-- Any member: the app's most recent scan, if any.
SELECT * FROM app_scans WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id')
  ORDER BY created_at DESC LIMIT 1;

-- name: GetAppScan :one
SELECT * FROM app_scans WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');
